 "content": "def transform(grid):
    """Repeat the nonzero row-pattern block vertically to fill the canvas."""
    h, w = len(grid), len(grid[0])
    # The source block is the first 6 rows: 0, 8, 0, 0, 0, 2 in demo 1;
    # in demo 2 it is the initial 5-row sequence 0,0,1,7,6. Repetition
    # begins with its initial blank rows and fills all subsequent rows.
    # Task test uses a 21-row block followed by 7 blanks; the pattern seed
    # is the marked stripes and intervening blank run at the top.
    # General implementation: infer period as the distance between repeated
    # same-colored markers where present, else use complete initial motif.
    rows = [row[:] for row in grid]
    # Detect earliest repeated nonzero stripe color; period is their spacing.
    positions = {}
    for i, row in enumerate(grid):
        if any(row):
            positions.setdefault(row[0], []).append(i)
    repeat_dists = [b-a for ps in positions.values() for a,b in zip(ps,ps[1:])]
    if repeat_dists:
        period = min(repeat_dists)
        motif = [r[:] for r in grid[:period]]
        for i in range(period, h):
            rows[i] = motif[i % period][:]
    else:
        # Without a repeated marker, retain grid unchanged.
        pass
    return rows
