 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Each full-width colored stripe anchors its color at its row phase in
    # the repeating horizontal-band cycle. The test anchors at rows 0, 4,
    # and 20 establish the 3-row cycle [5, 3, 7].
    anchors = [(i, row[0]) for i, row in enumerate(grid) if row[0] != 0]
    if not anchors:
        return [row[:] for row in grid]
    # Find the shortest period consistent with every anchor's row residue.
    for p in range(1, h + 1):
        phase = {}
        ok = True
        for i, color in anchors:
            k = i % p
            if k in phase and phase[k] != color:
                ok = False
                break
            phase[k] = color
        if ok:
            # Complete unanchored phases by repeating anchor colors cyclically
            # in their observed order, preserving all constrained phases.
            seq = [None] * p
            for k, color in phase.items():
                seq[k] = color
            known = [seq[k] for k in range(p) if seq[k] is not None]
            if not known:
                return [row[:] for row in grid]
            j = 0
            for k in range(p):
                if seq[k] is None:
                    seq[k] = known[j % len(known)]
                    j += 1
            return [[seq[i % p]] * w for i in range(h)]
    return [row[:] for row in grid]
